// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    // fuzz the caller 'from', a single recipient 'to' and a single amount so the loop is length 1
    function testFuzz_property(address from, uint256 amount, bool shouldFail) public {
        // keep _tos length 1 (we will construct the array below)
        vm.assume(from != address(0)); // keep a sensible from

        // deploy a helper that implements the correct selector and can optionally fail
        CalleeRecorder cal = new CalleeRecorder(shouldFail);

        // prepare arrays with exactly one element so behavior is deterministic across iterations
        address[] memory tos = new address[](1);
        tos[0] = address(cal);
        uint256[] memory vals = new uint256[](1);
        vals[0] = amount;

        // call C.transfer and observe whether it reverts via try/catch
        bool ok;
        try c.transfer(from, address(cal), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assert): The reference implementation always succeeds
        // when calling a callee that implements transferFrom(...). Our CalleeRecorder
        // implements that function; it will only cause the call to fail if shouldFail
        // is true. Therefore, for the reference contract, ok == true for all inputs
        // (because the callee's transferFrom executes and returns true). The mutant
        // that uses a wrong selector may make the low-level call fail and thus make
        // ok == false for some inputs. We assert that ok == !shouldFail (i.e., if the
        // callee is set to succeed, the transfer must succeed for all fuzz inputs).
        assertTrue( ok == (!shouldFail) );
    }
}

// Helper that implements the exact selector bytes4(keccak256("transferFrom(address,address,uint256)"))
// and can be toggled to revert to simulate a failing external party.
contract CalleeRecorder {
    bool public shouldFail;
    uint256 public calls;
    address public lastFrom;
    address public lastTo;
    uint256 public lastVal;

    constructor(bool _shouldFail) {
        shouldFail = _shouldFail;
    }

    // exact signature expected by C's transfer (so well-formed selector matches)
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        lastFrom = from;
        lastTo = to;
        lastVal = v;
        if (shouldFail) {
            revert("forced");
        }
        return true;
    }

    // fallback to catch malformed selectors (mutant will hit this and it will return true by default)
    fallback() external payable {
        // do nothing; returning successfully (i.e., not reverting) causes the low-level call to succeed
    }
}
